INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('28877e7a-19bb-4112-8d6b-35c9f4fa5653', '21feff02-016d-46e2-bb9d-c27495133b1b', '128. óra: Mindennapi pénzügyeink I.', 'Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "645e55c7-e8a6-4e8c-bf84-2d2f08fc2d9c", "text": "Mit jelent a banki megtakarítás (betét) után járó ''kamat''?", "type": "multiple-choice", "options": [{"id": "ff531e15-2c30-423d-813b-639edd4f1b6f", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "38c4f414-be3f-45ce-b910-ba56fa407937", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "ecc064e8-35d0-4d31-9b05-0214d3216e8d", "text": "A büntetés", "isCorrect": false}, {"id": "0517cad0-b056-44ed-9d99-9dbc78951878", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "c7c0d7e7-21f2-46cb-a8e0-4caea3d0ce87", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "5aece2a5-5a21-42f3-9b94-971aea978a9c", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "35d3d50c-9aad-4693-ad9a-5718939560cd", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "8e2df17c-251f-4907-bf9f-291f21e6e8b5", "text": "Igaz", "isCorrect": true}, {"id": "78aff0a1-5e2e-4483-9ab8-b92a3ad34d9f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a172e08d-016c-4c07-baab-865d0ecacfaa", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "7137a04c-8c2f-4ed0-801a-2b606e8c08dc", "text": "Igaz", "isCorrect": true}, {"id": "d56e728d-842c-4404-97a4-2716a32bf64d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "39e50941-aab2-42a1-9c28-080d9c71497d", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "e2dd675b-5f47-4ea6-a9c8-7603090579a7", "text": "Igaz", "isCorrect": true}, {"id": "31179237-4a75-4adf-b40e-5a2064c46016", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bc53fec7-205b-4f6c-adc5-1bcf4cb5e1b0", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]'::jsonb, true, NOW()),
('03b79be8-7828-41a2-8c66-98d6108296d5', '21feff02-016d-46e2-bb9d-c27495133b1b', '129. óra: Mindennapi pénzügyeink II.', 'Devizák, valutavételi és -eladási árfolyam, valutaváltás.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "c1609e87-e788-43fe-a05e-f50c80a4b527", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "accb691a-51a8-4b8d-93c4-96a48392ed61", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "a28a9243-0b5d-4026-98e3-0fd4385a9057", "text": "A bankjegy színe", "isCorrect": false}, {"id": "0901e4b1-6a66-4409-b31b-fb8852cfc926", "text": "A pénz súlya", "isCorrect": false}, {"id": "cedbacce-41aa-4dbc-a85f-cb37327fa2f4", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "4d519a34-6a97-4b5d-9ccc-366a34945873", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "b33a0069-3de4-4e64-a722-15825eabfe6b", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "8a7f6ea1-43ac-48e4-a8b8-26353826be7c", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "0dc2c6c5-df22-4258-a31e-4d807b2f9680", "text": "Igaz", "isCorrect": true}, {"id": "a157f589-a99b-4792-af5c-9792f121552a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d3b4f502-edf9-4690-9cb4-c190e088912f", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "af7aadf7-9d56-45cc-98a6-2faf088d2421", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "9611fe26-1220-4c73-ba46-024a4631a17c", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "35b79d42-ac95-454b-af58-111a9b698c7c", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "a0648d60-29eb-44a6-83e4-9e2a48d14972", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "cc60b219-9f9f-4c49-823f-80451f4d65b9", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "c4b5fe91-2ab8-492f-b5e4-fbf0ffc1077b", "text": "Igaz", "isCorrect": true}, {"id": "c3cf699c-b0c9-466b-950d-138ac34f06b9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9948fe21-cf06-4c03-a223-184a7de320cc", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]'::jsonb, true, NOW()),
('f7d99bad-0ca0-4324-a597-e89dbf7b4e0e', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "8cf8ee79-c0d4-453d-9675-9171bd5c4f42", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "a01da239-2939-4cfb-b1e4-2ce4fd37ab33", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "016c1fd0-d4a3-465c-b977-3a4bf4dedbb8", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "897ff8f2-438f-4bd1-befe-2124963ffe59", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "4b33abd7-e32d-4717-8dc7-5578c01eac10", "text": "Igaz", "isCorrect": true}, {"id": "5e4411a5-b7e0-40f8-9b32-572c376535ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "68a48734-c16a-46f8-a8bc-76ecfb5a1bd7", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "2056a66b-2904-4851-89a2-d721bb6ee261", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "4874aa70-d462-408e-ae40-cd76c8ee27d2", "text": "-4", "isCorrect": true}, {"id": "558225e0-2dca-49b7-84a1-64d20694b54c", "text": "-12", "isCorrect": false}, {"id": "d8ddb3d7-20ba-4946-861f-850e5cdc157f", "text": "Egyenlők", "isCorrect": false}, {"id": "b82d0576-dc05-401b-8739-ad72fae1e29f", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "44ade902-76c3-47ca-aaa8-5530658700d4", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW()),
('6d38f2d8-5cd2-4040-bf95-1727fb092a33', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "20d81453-0342-4742-947b-9fef6b108eab", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "6e1e3844-6355-410d-8211-ed819fdc47b1", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "1c726a8d-d5e4-4568-9347-a1c81c81ca75", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2072f3f0-db6e-4b4f-a2a9-a904270d991c", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "2241ab8d-24ab-413d-8648-4829b00e6633", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "298b6804-a0d3-4125-a269-4c4427a29b3d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b32db57-ad4f-4e92-b5a4-67cb8ed24736", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "e9fdb48d-07e5-4b02-b7b2-11e7cd8b4820", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "cc3d7d32-1cb2-4daa-b25e-97b49e939a0f", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "62230d0e-9696-451e-86bd-847f5f05ca5f", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "b77f5420-a990-4f38-bc8c-b8242d77857d", "text": "Igaz", "isCorrect": true}, {"id": "fb95ee66-f7fb-4db3-a144-509be1342ecc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c19a14b9-f9aa-4527-85e9-e9924616b199", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "1d4507ea-d86f-46fd-b213-dda88029c8bd", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "9d74c294-f436-437a-886b-d0380716ce39", "text": "815", "isCorrect": false}, {"id": "65b47929-2628-4f08-8db8-12be24b87943", "text": "812", "isCorrect": false}, {"id": "09edb7cd-ac5b-48a0-8ed6-0d8be58775a3", "text": "811", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('a031f61d-f76a-4bf8-b053-1a7f4b708cca', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "812375f7-59b7-4933-a67f-81523460b2cb", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "308b91f4-b9f9-4867-b314-65907da6e3d1", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "d933aa45-7964-4bb2-9727-5110d0f98615", "text": "4/6", "isCorrect": false}, {"id": "f7b921c8-9165-45db-b702-8709dab36c2e", "text": "4/4", "isCorrect": false}, {"id": "bb639704-0864-449b-9f09-d792eee55c19", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "7133dc94-ceb2-41de-8954-371bb83ba583", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "b7fe2251-d01d-4816-91da-75436de40659", "text": "2/5", "isCorrect": true}, {"id": "21010977-3158-4ba3-8b0e-fdc33664e390", "text": "6/15", "isCorrect": false}, {"id": "e704ed03-a84e-48d3-8849-6d9ab9875e29", "text": "5/8", "isCorrect": false}, {"id": "2b9ddca9-5fc2-4882-a7a2-6b24fe9b53d3", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "57784be5-538d-4693-a5c2-6e9dad821b9f", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "7132713b-9c54-40cb-95f1-53ef4cedc1de", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "42db60d5-9f1e-4041-a9ac-181c14288e28", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "575bef25-eda1-4ff7-b864-5924d611785c", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "13862a03-c790-4cee-8894-3573bb308f36", "text": "Igaz", "isCorrect": true}, {"id": "175cf2c2-4c09-41dc-8bcb-fd4c4d730adb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "962b3aef-7a53-4db2-9729-bebe65e49044", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());